/**
 * Unmodified fixture Mod for the Stent API assembled-composition test: a
 * plain Cordis plugin that imports ONLY the Stent API contracts and
 * contributes an agent listener, a tool, prompt sections/variables, and a
 * human command. The assembly spec asserts every contribution through the
 * authoritative services and observes the agent listener through the real
 * event bus.
 */

export const name = 'stent-api-fixture-mod'
export const inject = ['stentAgent', 'stentTools', 'stentPrompt', 'stentCommands']

const seen = []
globalThis.__stentApiFixtureSeen = seen

export function apply(ctx) {
  ctx.stentAgent.onStatus((agent, status) => {
    seen.push(`${agent.id}:${status}`)
  })

  ctx.stentTools.register({
    name: 'mod-fixture-tool',
    description: 'fixture tool',
    parameters: { text: { type: 'string' } },
    output: {
      schema: { type: 'string' },
      render: (_args, value) => [{ type: 'text', text: value }],
    },
    async execute(args) {
      return args.text ?? ''
    },
  })

  ctx.stentPrompt.section({ name: 'mod-fixture-section', order: -40, text: 'fixture section {{fixture_var}}' })
  ctx.stentPrompt.context({ name: 'mod-fixture-context', order: 1, text: 'fixture context' })
  ctx.stentPrompt.variable('fixture_var', () => 'fixture-value')

  ctx.stentCommands.register({
    name: 'modfixture',
    description: 'fixture command',
    handler: () => ({ kind: 'success', text: 'fixture ok' }),
  })
}
